            await _waitFlow();
          }
          if (_closed) throw StateError('transport closed');
          final sw = _streamWindows[streamId] ?? _peerInitialWindow;
          var allowance = _connWindow < sw ? _connWindow : sw;
          final remaining = wire.length - sent;
          if (allowance > maxFramePayload) allowance = maxFramePayload;
          if (allowance > remaining) allowance = remaining;
          if (allowance <= 0) {
            await _waitFlow();
            continue;
          }
          _connWindow -= allowance;
          _streamWindows[streamId] = sw - allowance;
          _writeFrame(h2Data, 0, streamId,
              Uint8List.sublistView(wire, sent, sent + allowance));
          sent += allowance;
        }
        break;
      case Wire.frameHalfClose:
        _writeFrame(h2Data, flagEndStream, streamId, Uint8List(0));
        break;
      case Wire.frameRst:
        _writeFrame(h2RstStream, 0, streamId,
            Uint8List.fromList([0, 0, 0, 8]));
        break;
      default:
        // Trailers never travel client -> server here.
        break;
    }
  }

  static void _writeInt(BytesBuilder out, int value, int prefixBits, int prefix) {
    final mask = (1 << prefixBits) - 1;
    if (value < mask) {
      out.addByte(prefix | value);
      return;
    }
    out.addByte(prefix | mask);
    var rest = value - mask;
    while (rest >= 0x80) {
      out.addByte((rest & 0x7f) | 0x80);
      rest >>= 7;
    }
    out.addByte(rest);
  }

  static void _writeString(BytesBuilder out, String value) {
    final raw = utf8.encode(value);
    _writeInt(out, raw.length, 7, 0);
    out.add(raw);
  }

  static void _writeLiteralIndexedName(BytesBuilder out, int index, String value) {
    _writeInt(out, index, 4, 0);
    _writeString(out, value);
  }

  static void _writeLiteralNewName(BytesBuilder out, String name, String value) {
    _writeInt(out, 0, 4, 0);
    _writeString(out, name);
    _writeString(out, value);
  }
}

class _HpackDecoder {
  final List<(String, String)> _dynamic = [];
  int _dynamicSize = 0;
  static const int maxDynamic = 4096;

  (String, String) _entry(int index) {
    if (index <= 0) {
      throw FormatException('bad hpack index 0');
    }
    if (index <= Http2Transport.staticTable.length) {
      final e = Http2Transport.staticTable[index - 1];
      return (e[0], e[1]);
    }
    final j = index - Http2Transport.staticTable.length - 1;
    if (j >= _dynamic.length) {
      throw FormatException('bad hpack dynamic index $index');
    }
    return _dynamic[j];
  }

  void _add(String name, String value) {
    _dynamic.insert(0, (name, value));
    _dynamicSize += name.length + value.length + 32;
    while (_dynamicSize > maxDynamic && _dynamic.isNotEmpty) {
      final e = _dynamic.removeLast();
      _dynamicSize -= e.$1.length + e.$2.length + 32;
    }
  }

  static int _readInt(Uint8List data, List<int> pos, int prefixBits) {
    final mask = (1 << prefixBits) - 1;
    var value = data[pos[0]] & mask;
    pos[0]++;
    if (value < mask) return value;
    var shift = 0;
    while (true) {
      if (pos[0] >= data.length) {
        throw const FormatException('truncated hpack int');
      }
      final b = data[pos[0]] & 0xff;
      pos[0]++;
      value += (b & 0x7f) << shift;
      shift += 7;
      if ((b & 0x80) == 0) break;
    }
    return value;
  }

  static String _readString(Uint8List data, List<int> pos) {
    if (pos[0] >= data.length) {
      throw const FormatException('truncated hpack string');
    }
    final huffman = (data[pos[0]] & 0x80) != 0;
    final len = _readInt(data, pos, 7);
    if (pos[0] + len > data.length) {
      throw const FormatException('truncated hpack string body');
    }
    final value = huffman
        ? Http2Transport.huffDecode(data, pos[0], len)
        : utf8.decode(Uint8List.sublistView(data, pos[0], pos[0] + len));
    pos[0] += len;
    return value;
  }

  List<(String, String)> decode(Uint8List block) {
    final out = <(String, String)>[];
    final pos = [0];
    while (pos[0] < block.length) {
      final b = block[pos[0]] & 0xff;
      if ((b & 0x80) != 0) {
        final index = _readInt(block, pos, 7);
        out.add(_entry(index));
      } else if ((b & 0xe0) == 0x20) {
        _readInt(block, pos, 5);
      } else {
        final incremental = (b & 0xc0) == 0x40;
        final index = _readInt(block, pos, incremental ? 6 : 4);
        final name = index > 0 ? _entry(index).$1 : _readString(block, pos);
        final value = _readString(block, pos);
        out.add((name, value));
        if (incremental) _add(name, value);
      }
    }
    return out;
  }
}
